     1→//! Gradient checking tests - THE MOST IMPORTANT TESTS (M6)
     2→//!
     3→//! These tests verify that analytical gradients match numerical gradients
     4→//! computed via finite differences. This is critical for correct training.
     5→//!
     6→//! For every differentiable operation, we test:
     7→//! - Numerical: (f(x+ε) - f(x-ε)) / 2ε
     8→//! - Analytical: backward pass implementation
     9→//! - Assert relative error < 1e-4
    10→
    11→#[cfg(test)]
    12→mod tests {
    13→    use nalgebra::Vector3;
    14→    use rand::rngs::StdRng;
    15→    use rand::{Rng, SeedableRng};
    16→
    17→    use sugar_rs::core::{evaluate_sh, inverse_sigmoid, perspective_jacobian, sh_basis, sigmoid};
    18→    use sugar_rs::diff::blend_grad::{blend_backward, blend_forward};
    19→    use sugar_rs::diff::covariance_grad::project_covariance_2d_grad_point_cam;
    20→    use sugar_rs::diff::covariance_grad::{
    21→        project_covariance_2d_grad_log_scale, project_covariance_2d_grad_rotation_vector_at_r0,
    22→    };
    23→    use sugar_rs::diff::gaussian2d_grad::gaussian2d_evaluate_with_grads;
    24→    use sugar_rs::diff::math_grad::{inverse_sigmoid_grad, sigmoid_grad_from_sigmoid};
    25→    use sugar_rs::diff::project_grad::project_point_grad_point_cam;
    26→    use sugar_rs::diff::quaternion_grad::{
    27→        quaternion_raw_to_matrix, quaternion_raw_to_matrix_grad,
    28→    };
    29→    use sugar_rs::diff::sh_grad::evaluate_sh_grad_coeffs;
    30→
    31→    // These tests are NON-NEGOTIABLE - bugs in gradients cause silent failures.
    32→    fn rel_err(a: f32, b: f32) -> f32 {
    33→        let denom = a.abs().max(b.abs()).max(1e-6);
    34→        (a - b).abs() / denom
    35→    }
    36→
    37→    #[test]
    38→    fn test_sigmoid_gradient() {
    39→        // Gradient check for:
    40→        // - sigmoid(x) w.r.t x
    41→        // - inverse_sigmoid(p) w.r.t p  (away from clamp)
    42→        let mut rng = StdRng::seed_from_u64(0x51C1_01D_u64);
    43→
    44→        // Sigmoid: choose x in a moderate range to avoid saturation.
    45→        for _ in 0..200 {
    46→            let x = rng.gen_range(-4.0..4.0);
    47→            let eps = 1e-2f32;
    48→
    49→            let f = |v: f32| sigmoid(v);
    50→            let f_plus = f(x + eps) as f64;
    51→            let f_minus = f(x - eps) as f64;
    52→            let num = ((f_plus - f_minus) / (2.0 * eps as f64)) as f32;
    53→
    54→            let s = sigmoid(x);
    55→            let ana = sigmoid_grad_from_sigmoid(s);
    56→
    57→            let abs_err = (num - ana).abs();
    58→            assert!(
    59→                rel_err(num, ana) < 1e-4 || abs_err < 1e-5,
    60→                "sigmoid grad mismatch: x={x} num={num} ana={ana} abs_err={abs_err} rel_err={}",
    61→                rel_err(num, ana)
    62→            );
    63→        }
    64→
    65→        // inverse_sigmoid (logit): choose p safely away from clamp and 0/1.
    66→        // Near 0/1 the derivative explodes, which makes finite differences noisy in f32.
    67→        for _ in 0..200 {
    68→            let p = rng.gen_range(0.1..0.9);
    69→            let eps = 1e-3f32;
    70→
    71→            let f = |v: f32| inverse_sigmoid(v);
    72→            let num = ((f(p + eps) as f64 - f(p - eps) as f64) / (2.0 * eps as f64)) as f32;
    73→            let ana = inverse_sigmoid_grad(p);
    74→
    75→            let abs_err = (num - ana).abs();
    76→            assert!(
    77→                rel_err(num, ana) < 1e-4 || abs_err < 1e-5,
    78→                "inverse_sigmoid grad mismatch: p={p} num={num} ana={ana} abs_err={abs_err} rel_err={}",
    79→                rel_err(num, ana)
    80→            );
    81→        }
    82→    }
    83→
    84→    #[test]
    85→    fn test_quaternion_to_matrix_gradient() {
    86→        // Gradient check for raw quaternion (w,x,y,z) -> rotation matrix conversion.
    87→        //
    88→        // We parameterize with a raw 4-vector and normalize inside the function.
    89→        let mut rng = StdRng::seed_from_u64(0x0A76_A4D1_u64);
    90→        let tol = 5e-4f32;
    91→
    92→        for _ in 0..200 {
    93→            // Random non-zero quaternion raw parameters.
    94→            let mut q_raw = nalgebra::Vector4::new(
    95→                rng.gen_range(-1.0f32..1.0f32),
    96→                rng.gen_range(-1.0f32..1.0f32),
    97→                rng.gen_range(-1.0f32..1.0f32),
    98→                rng.gen_range(-1.0f32..1.0f32),
    99→            );
   100→            if q_raw.norm() < 1e-3 {
   101→                q_raw.x = 1.0;
   102→            }
   103→
   104→            // Upstream gradient dL/dR.
   105→            let d_r = nalgebra::Matrix3::new(
   106→                rng.gen_range(-1.0f32..1.0f32),
   107→                rng.gen_range(-1.0f32..1.0f32),
   108→                rng.gen_range(-1.0f32..1.0f32),
   109→                rng.gen_range(-1.0f32..1.0f32),
   110→                rng.gen_range(-1.0f32..1.0f32),
   111→                rng.gen_range(-1.0f32..1.0f32),
   112→                rng.gen_range(-1.0f32..1.0f32),
   113→                rng.gen_range(-1.0f32..1.0f32),
   114→                rng.gen_range(-1.0f32..1.0f32),
   115→            );
   116→
   117→            let ana = quaternion_raw_to_matrix_grad(&q_raw, &d_r);
   118→
   119→            // Scalar loss L = <d_r, R(q_raw)>
   120→            let loss = |q: &nalgebra::Vector4<f32>| -> f64 {
   121→                let r = quaternion_raw_to_matrix(q);
   122→                (r[(0, 0)] as f64) * (d_r[(0, 0)] as f64)
   123→                    + (r[(0, 1)] as f64) * (d_r[(0, 1)] as f64)
   124→                    + (r[(0, 2)] as f64) * (d_r[(0, 2)] as f64)
   125→                    + (r[(1, 0)] as f64) * (d_r[(1, 0)] as f64)
   126→                    + (r[(1, 1)] as f64) * (d_r[(1, 1)] as f64)
   127→                    + (r[(1, 2)] as f64) * (d_r[(1, 2)] as f64)
   128→                    + (r[(2, 0)] as f64) * (d_r[(2, 0)] as f64)
   129→                    + (r[(2, 1)] as f64) * (d_r[(2, 1)] as f64)
   130→                    + (r[(2, 2)] as f64) * (d_r[(2, 2)] as f64)
   131→            };
   132→
   133→            let eps = 1e-3f32;
   134→            for k in 0..4 {
   135→                let mut plus = q_raw;
   136→                let mut minus = q_raw;
   137→                plus[k] += eps;
   138→                minus[k] -= eps;
   139→
   140→                let num = ((loss(&plus) - loss(&minus)) / (2.0 * eps as f64)) as f32;
   141→                let got = ana[k];
   142→                let abs_err = (got - num).abs();
   143→                assert!(
   144→                    rel_err(got, num) < tol || abs_err < 5e-4,
   145→                    "quat->mat grad mismatch k={k}: num={num} ana={got} abs_err={abs_err} rel_err={}",
   146→                    rel_err(got, num)
   147→                );
   148→            }
   149→        }
   150→    }
