   152→    #[test]
   153→    fn test_rotation_to_covariance_gradient() {
   154→        // Gradient check for local rotation-vector parameterization ω around a base rotation R0.
   155→        // This checks the rotation -> covariance -> projection chain without quaternions.
   156→        let mut rng = StdRng::seed_from_u64(0xA11C_E501_u64);
   157→        let tol_f32 = 5e-4f32;
   158→
   159→        for _ in 0..100 {
   160→            let cam_q = nalgebra::UnitQuaternion::from_euler_angles(
   161→                rng.gen_range(-1.0f32..1.0f32),
   162→                rng.gen_range(-1.0f32..1.0f32),
   163→                rng.gen_range(-1.0f32..1.0f32),
   164→            );
   165→            let w = cam_q.to_rotation_matrix().into_inner();
   166→
   167→            let g_q = nalgebra::UnitQuaternion::from_euler_angles(
   168→                rng.gen_range(-1.0f32..1.0f32),
   169→                rng.gen_range(-1.0f32..1.0f32),
   170→                rng.gen_range(-1.0f32..1.0f32),
   171→            );
   172→            let r0 = g_q.to_rotation_matrix().into_inner();
   173→
   174→            let point_cam = nalgebra::Vector3::new(
   175→                rng.gen_range(-0.5f32..0.5f32),
   176→                rng.gen_range(-0.5f32..0.5f32),
   177→                rng.gen_range(1.0f32..4.0f32),
   178→            );
   179→            let fx = rng.gen_range(100.0f32..400.0f32);
   180→            let fy = rng.gen_range(100.0f32..400.0f32);
   181→            let j = perspective_jacobian(&point_cam, fx, fy);
   182→
   183→            let log_scale = nalgebra::Vector3::new(
   184→                rng.gen_range(-4.0f32..-0.5f32),
   185→                rng.gen_range(-4.0f32..-0.5f32),
   186→                rng.gen_range(-4.0f32..-0.5f32),
   187→            );
   188→
   189→            let g00 = rng.gen_range(-1.0f32..1.0f32);
   190→            let g01 = rng.gen_range(-1.0f32..1.0f32);
   191→            let g11 = rng.gen_range(-1.0f32..1.0f32);
   192→            let d_sigma2d = nalgebra::Matrix2::new(g00, g01, g01, g11);
   193→
   194→            let grad_f32 = project_covariance_2d_grad_rotation_vector_at_r0(
   195→                &w, &j, &r0, &log_scale, &d_sigma2d,
   196→            );
   197→
   198→            // f64 forward for numeric gradient.
   199→            let w64 = w.map(|x| x as f64);
   200→            let j64 = j.map(|x| x as f64);
   201→            let d64 = d_sigma2d.map(|x| x as f64);
   202→            let log_scale64 = log_scale.map(|x| x as f64);
   203→            let r0_64 = r0.map(|x| x as f64);
   204→
   205→            let d_vec = nalgebra::Vector3::new(
   206→                (2.0 * log_scale64.x).exp(),
   207→                (2.0 * log_scale64.y).exp(),
   208→                (2.0 * log_scale64.z).exp(),
   209→            );
   210→            let d_mat = nalgebra::Matrix3::from_diagonal(&d_vec);
   211→
   212→            let loss64 = |r: nalgebra::Matrix3<f64>| -> f64 {
   213→                let sigma = r * d_mat * r.transpose();
   214→                let sigma_cam = w64 * sigma * w64.transpose();
   215→                let sigma2d = j64 * sigma_cam * j64.transpose();
   216→                (sigma2d.component_mul(&d64)).sum()
   217→            };
   218→
   219→            let rot_x = |theta: f64| -> nalgebra::Matrix3<f64> {
   220→                let (s, c) = theta.sin_cos();
   221→                nalgebra::Matrix3::new(1.0, 0.0, 0.0, 0.0, c, -s, 0.0, s, c)
   222→            };
   223→            let rot_y = |theta: f64| -> nalgebra::Matrix3<f64> {
   224→                let (s, c) = theta.sin_cos();
   225→                nalgebra::Matrix3::new(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c)
   226→            };
   227→            let rot_z = |theta: f64| -> nalgebra::Matrix3<f64> {
   228→                let (s, c) = theta.sin_cos();
   229→                nalgebra::Matrix3::new(c, -s, 0.0, s, c, 0.0, 0.0, 0.0, 1.0)
   230→            };
   231→
   232→            let eps = 1e-4f64;
   233→            let num_x = (loss64(rot_x(eps) * r0_64) - loss64(rot_x(-eps) * r0_64)) / (2.0 * eps);
   234→            let num_y = (loss64(rot_y(eps) * r0_64) - loss64(rot_y(-eps) * r0_64)) / (2.0 * eps);
   235→            let num_z = (loss64(rot_z(eps) * r0_64) - loss64(rot_z(-eps) * r0_64)) / (2.0 * eps);
   236→
   237→            let num = nalgebra::Vector3::new(num_x as f32, num_y as f32, num_z as f32);
   238→
   239→            for axis in 0..3 {
   240→                let got = grad_f32[axis];
   241→                let reference = num[axis];
   242→                let abs_err = (got - reference).abs();
   243→                assert!(
   244→                    rel_err(got, reference) < tol_f32 || abs_err < 5e-4,
   245→                    "rot->cov grad mismatch axis={axis}: num={reference} ana={got} abs_err={abs_err} rel_err={}",
   246→                    rel_err(got, reference)
   247→                );
   248→            }
   249→        }
   250→    }
   251→
   252→    #[test]
   253→    fn test_covariance_projection_gradient() {
   254→        // Gradient check for 3D -> 2D covariance projection w.r.t. log-scales (scale-only).
   255→        //
   256→        // This holds rotation and the perspective Jacobian fixed. We'll extend to rotation/J later.
   257→        let mut rng = StdRng::seed_from_u64(0xC0A2_D5CA_u64);
   258→        let tol = 5e-4f32;
   259→
   260→        for _ in 0..200 {
   261→            // Random camera rotation (orthonormal via nalgebra quaternion).
   262→            let cam_q = nalgebra::UnitQuaternion::from_euler_angles(
   263→                rng.gen_range(-1.0f32..1.0f32),
   264→                rng.gen_range(-1.0f32..1.0f32),
   265→                rng.gen_range(-1.0f32..1.0f32),
   266→            );
   267→            let w = cam_q.to_rotation_matrix().into_inner();
   268→
   269→            // Random gaussian rotation.
   270→            let g_q = nalgebra::UnitQuaternion::from_euler_angles(
   271→                rng.gen_range(-1.0f32..1.0f32),
   272→                rng.gen_range(-1.0f32..1.0f32),
   273→                rng.gen_range(-1.0f32..1.0f32),
   274→            );
   275→            let r = g_q.to_rotation_matrix().into_inner();
   276→
   277→            // Point in camera space for Jacobian.
   278→            let point_cam = nalgebra::Vector3::new(
   279→                rng.gen_range(-0.5f32..0.5f32),
   280→                rng.gen_range(-0.5f32..0.5f32),
   281→                rng.gen_range(1.0f32..4.0f32),
   282→            );
   283→            // Keep intrinsics modest to avoid huge loss magnitudes (which make finite differences noisy in f32).
   284→            let fx = rng.gen_range(100.0f32..400.0f32);
   285→            let fy = rng.gen_range(100.0f32..400.0f32);
   286→            let j = perspective_jacobian(&point_cam, fx, fy);
   287→
   288→            // Log-scales in a modest range.
   289→            let log_scale = nalgebra::Vector3::new(
   290→                rng.gen_range(-4.0f32..-0.5f32),
   291→                rng.gen_range(-4.0f32..-0.5f32),
   292→                rng.gen_range(-4.0f32..-0.5f32),
   293→            );
   294→
   295→            // Upstream gradient for Σ₂d: pick a symmetric matrix.
   296→            let g00 = rng.gen_range(-1.0f32..1.0f32);
   297→            let g01 = rng.gen_range(-1.0f32..1.0f32);
   298→            let g11 = rng.gen_range(-1.0f32..1.0f32);
   299→            let d_sigma2d = nalgebra::Matrix2::new(g00, g01, g01, g11);
   300→
   301→            // Compute production (f32) analytic gradient.
   302→            let d_log_scale_f32 =
   303→                project_covariance_2d_grad_log_scale(&w, &j, &r, &log_scale, &d_sigma2d);
   304→
   305→            // For a stable gradient check, compute forward + analytic gradient in f64.
   306→            let w64 = w.map(|x| x as f64);
   307→            let r64 = r.map(|x| x as f64);
   308→            let j64 = j.map(|x| x as f64);
   309→            let g64 = d_sigma2d.map(|x| x as f64);
   310→            let log_scale64 = log_scale.map(|x| x as f64);
   311→
   312→            let loss64 = |s: nalgebra::Vector3<f64>| -> f64 {
   313→                let sigma2d = {
   314→                    let v = nalgebra::Vector3::new(
   315→                        (2.0 * s.x).exp(),
   316→                        (2.0 * s.y).exp(),
   317→                        (2.0 * s.z).exp(),
   318→                    );
   319→                    let d = nalgebra::Matrix3::from_diagonal(&v);
   320→                    let sigma = r64 * d * r64.transpose();
   321→                    let sigma_cam = w64 * sigma * w64.transpose();
   322→                    j64 * sigma_cam * j64.transpose()
   323→                };
   324→                (sigma2d.component_mul(&g64)).sum()
   325→            };
   326→
   327→            let grad64 = |s: nalgebra::Vector3<f64>| -> nalgebra::Vector3<f64> {
   328→                let v =
   329→                    nalgebra::Vector3::new((2.0 * s.x).exp(), (2.0 * s.y).exp(), (2.0 * s.z).exp());
   330→                let d_sigma_cam: nalgebra::Matrix3<f64> = j64.transpose() * g64 * j64;
   331→                let d_sigma = w64.transpose() * d_sigma_cam * w64;
   332→                let m = r64.transpose() * d_sigma * r64;
   333→                nalgebra::Vector3::new(
   334→                    m[(0, 0)] * 2.0 * v.x,
   335→                    m[(1, 1)] * 2.0 * v.y,
   336→                    m[(2, 2)] * 2.0 * v.z,
   337→                )
   338→            };
   339→
   340→            let ana64 = grad64(log_scale64);
   341→
   342→            // Finite differences for each scale component (f64).
   343→            for axis in 0..3 {
   344→                let eps = 1e-4f64;
   345→                let mut plus = log_scale64;
   346→                let mut minus = log_scale64;
   347→                plus[axis] += eps;
   348→                minus[axis] -= eps;
   349→
   350→                let num = (loss64(plus) - loss64(minus)) / (2.0 * eps);
   351→                let ana = ana64[axis];
   352→                let denom = num.abs().max(ana.abs()).max(1e-9);
   353→                let rel = (num - ana).abs() / denom;
   354→                assert!(
   355→                    rel < 1e-6,
   356→                    "cov proj grad mismatch axis={axis}: num={num} ana={ana} rel={rel}"
   357→                );
   358→
   359→                // Also ensure our f32 implementation matches the f64 analytic result.
   360→                let ana_f32_ref = ana as f32;
   361→                let got = d_log_scale_f32[axis];
   362→                let abs_err = (got - ana_f32_ref).abs();
   363→                assert!(
   364→                    rel_err(got, ana_f32_ref) < tol || abs_err < 5e-4,
   365→                    "cov proj f32 mismatch axis={axis}: got={got} ref={ana_f32_ref} abs_err={abs_err} rel_err={}",
   366→                    rel_err(got, ana_f32_ref)
