   372→    #[test]
   373→    fn test_gaussian_2d_evaluation_gradient() {
   374→        // Gradient check for 2D Gaussian evaluation w.r.t mean and covariance entries.
   375→        //
   376→        // This test uses a well-conditioned covariance to avoid any stabilization branches.
   377→        let mut rng = StdRng::seed_from_u64(0xD00D_2D_u64);
   378→        let tol = 5e-4f32;
   379→
   380→        for _ in 0..200 {
   381→            // Random mean and pixel within a modest range.
   382→            let mean = Vector3::new(rng.gen_range(-1.0..1.0), rng.gen_range(-1.0..1.0), 0.0);
   383→            let pixel = Vector3::new(rng.gen_range(-1.0..1.0), rng.gen_range(-1.0..1.0), 0.0);
   384→
   385→            // SPD covariance with controlled off-diagonal.
   386→            let cov_xx = rng.gen_range(0.5f32..2.0f32);
   387→            let cov_yy = rng.gen_range(0.5f32..2.0f32);
   388→            let max_b = 0.25 * (cov_xx * cov_yy).sqrt();
   389→            let cov_xy = rng.gen_range(-max_b..max_b);
   390→
   391→            let det = cov_xx * cov_yy - cov_xy * cov_xy;
   392→            assert!(det > 0.1, "det too small for stable test: {det}");
   393→
   394→            let grads = gaussian2d_evaluate_with_grads(
   395→                nalgebra::Vector2::new(mean.x, mean.y),
   396→                cov_xx,
   397→                cov_xy,
   398→                cov_yy,
   399→                nalgebra::Vector2::new(pixel.x, pixel.y),
   400→            );
   401→
   402→            // Mean gradients (finite difference on mx, my).
   403→            for (which, ana) in [("mx", grads.d_mean.x), ("my", grads.d_mean.y)] {
   404→                let eps = 1e-3f32;
   405→                let f = |mx: f32, my: f32| -> f32 {
   406→                    gaussian2d_evaluate_with_grads(
   407→                        nalgebra::Vector2::new(mx, my),
   408→                        cov_xx,
   409→                        cov_xy,
   410→                        cov_yy,
   411→                        nalgebra::Vector2::new(pixel.x, pixel.y),
   412→                    )
   413→                    .value
   414→                };
   415→
   416→                let (plus, minus) = match which {
   417→                    "mx" => (f(mean.x + eps, mean.y), f(mean.x - eps, mean.y)),
   418→                    "my" => (f(mean.x, mean.y + eps), f(mean.x, mean.y - eps)),
   419→                    _ => unreachable!(),
   420→                };
   421→                let num = ((plus as f64 - minus as f64) / (2.0 * eps as f64)) as f32;
   422→
   423→                let abs_err = (num - ana).abs();
   424→                assert!(
   425→                    rel_err(num, ana) < tol || abs_err < 2e-4,
   426→                    "2D eval mean grad mismatch {which}: num={num} ana={ana} abs_err={abs_err} rel_err={}",
   427→                    rel_err(num, ana)
   428→                );
   429→            }
   430→
   431→            // Covariance gradients (finite difference on a,b,c).
   432→            let eps = 1e-2f32;
   433→            let f = |a: f32, b: f32, c: f32| -> f32 {
   434→                gaussian2d_evaluate_with_grads(
   435→                    nalgebra::Vector2::new(mean.x, mean.y),
   436→                    a,
   437→                    b,
   438→                    c,
   439→                    nalgebra::Vector2::new(pixel.x, pixel.y),
   440→                )
   441→                .value
   442→            };
   443→
   444→            let num_a = ((f(cov_xx + eps, cov_xy, cov_yy) as f64
   445→                - f(cov_xx - eps, cov_xy, cov_yy) as f64)
   446→                / (2.0 * eps as f64)) as f32;
   447→            let num_b = ((f(cov_xx, cov_xy + eps, cov_yy) as f64
   448→                - f(cov_xx, cov_xy - eps, cov_yy) as f64)
   449→                / (2.0 * eps as f64)) as f32;
   450→            let num_c = ((f(cov_xx, cov_xy, cov_yy + eps) as f64
   451→                - f(cov_xx, cov_xy, cov_yy - eps) as f64)
   452→                / (2.0 * eps as f64)) as f32;
   453→
   454→            for (name, num, ana) in [
   455→                ("cov_xx", num_a, grads.d_cov_xx),
   456→                ("cov_xy", num_b, grads.d_cov_xy),
   457→                ("cov_yy", num_c, grads.d_cov_yy),
   458→            ] {
   459→                let abs_err = (num - ana).abs();
   460→                assert!(
   461→                    rel_err(num, ana) < tol || abs_err < 2e-4,
   462→                    "2D eval cov grad mismatch {name}: num={num} ana={ana} abs_err={abs_err} rel_err={}",
   463→                    rel_err(num, ana)
   464→                );
   465→            }
   466→        }
   467→    }
