   469→    #[test]
   470→    fn test_alpha_blending_gradient() {
   471→        // Gradient check for front-to-back alpha compositing w.r.t.:
   472→        // - alphas a_i
   473→        // - colors c_i (RGB)
   474→        let mut rng = StdRng::seed_from_u64(0xB1ED_0BAD_u64);
   475→        let tol = 5e-4f32;
   476→
   477→        for _ in 0..200 {
   478→            let n = rng.gen_range(1..6);
   479→            let mut alphas = Vec::with_capacity(n);
   480→            let mut colors = Vec::with_capacity(n);
   481→
   482→            // Keep alpha away from 0/1 to avoid extremely small transmittance and numerical issues.
   483→            for _ in 0..n {
   484→                alphas.push(rng.gen_range(0.05f32..0.5f32));
   485→                colors.push(Vector3::new(
   486→                    rng.gen_range(0.0f32..1.0f32),
   487→                    rng.gen_range(0.0f32..1.0f32),
   488→                    rng.gen_range(0.0f32..1.0f32),
   489→                ));
   490→            }
   491→
   492→            let forward = blend_forward(&alphas, &colors);
   493→
   494→            // Loss: L = w · out
   495→            let w = Vector3::new(
   496→                rng.gen_range(-1.0f32..1.0f32),
   497→                rng.gen_range(-1.0f32..1.0f32),
   498→                rng.gen_range(-1.0f32..1.0f32),
   499→            );
   500→
   501→            let grads = blend_backward(&alphas, &colors, &forward, &w);
   502→
   503→            let eps = 1e-3f32;
   504→            let f = |a: &[f32], c: &[Vector3<f32>]| -> f32 {
   505→                let out = blend_forward(a, c).out;
   506→                w.dot(&out)
   507→            };
   508→
   509→            // Check alpha gradients.
   510→            for i in 0..n {
   511→                let mut a_plus = alphas.clone();
   512→                let mut a_minus = alphas.clone();
   513→                a_plus[i] += eps;
   514→                a_minus[i] -= eps;
   515→
   516→                let num = ((f(&a_plus, &colors) as f64 - f(&a_minus, &colors) as f64)
   517→                    / (2.0 * eps as f64)) as f32;
   518→                let ana = grads.d_alphas[i];
   519→                let abs_err = (num - ana).abs();
   520→                assert!(
   521→                    rel_err(num, ana) < tol || abs_err < 2e-4,
   522→                    "blend alpha grad mismatch i={i}: num={num} ana={ana} abs_err={abs_err} rel_err={}",
   523→                    rel_err(num, ana)
   524→                );
   525→            }
   526→
   527→            // Check a few random color components.
   528→            for _ in 0..5 {
   529→                let i = rng.gen_range(0..n);
   530→                let channel = rng.gen_range(0..3);
   531→
   532→                let mut c_plus = colors.clone();
   533→                let mut c_minus = colors.clone();
   534→                match channel {
   535→                    0 => {
   536→                        c_plus[i].x += eps;
   537→                        c_minus[i].x -= eps;
   538→                    }
   539→                    1 => {
   540→                        c_plus[i].y += eps;
   541→                        c_minus[i].y -= eps;
   542→                    }
   543→                    2 => {
   544→                        c_plus[i].z += eps;
   545→                        c_minus[i].z -= eps;
   546→                    }
   547→                    _ => unreachable!(),
   548→                }
   549→
   550→                let num = ((f(&alphas, &c_plus) as f64 - f(&alphas, &c_minus) as f64)
   551→                    / (2.0 * eps as f64)) as f32;
   552→                let ana = match channel {
   553→                    0 => grads.d_colors[i].x,
   554→                    1 => grads.d_colors[i].y,
   555→                    2 => grads.d_colors[i].z,
   556→                    _ => unreachable!(),
   557→                };
   558→
   559→                let abs_err = (num - ana).abs();
   560→                assert!(
   561→                    rel_err(num, ana) < tol || abs_err < 2e-4,
   562→                    "blend color grad mismatch i={i} ch={channel}: num={num} ana={ana} abs_err={abs_err} rel_err={}",
   563→                    rel_err(num, ana)
   564→                );
   565→            }
   566→        }
   567→    }
