   569→    #[test]
   570→    fn test_sh_evaluation_gradient() {
   571→        // Gradient check for SH evaluation w.r.t. coefficients.
   572→        //
   573→        // Forward:
   574→        //   color = sum_i basis[i] * sh_coeffs[i]   (per channel)
   575→        //
   576→        // Loss:
   577→        //   L = w · color
   578→        //
   579→        // Then dL/d(sh_coeffs[i][c]) = w[c] * basis[i]
   580→        //
   581→        // We choose small coefficients so `evaluate_sh`'s output clamp is inactive.
   582→        let mut rng = StdRng::seed_from_u64(0x5EED_5A5A_u64);
   583→        // Use an epsilon that adapts to the basis magnitude so the induced color delta
   584→        // is "big enough" for f32, but still far from the clamp region.
   585→        let target_delta = 0.05f32;
   586→        let tol = 1e-4f32;
   587→
   588→        for _ in 0..50 {
   589→            // Random direction (do NOT pre-normalize; `evaluate_sh` normalizes internally).
   590→            let mut dir_raw = Vector3::new(
   591→                rng.gen_range(-1.0..1.0),
   592→                rng.gen_range(-1.0..1.0),
   593→                rng.gen_range(-1.0..1.0),
   594→            );
   595→            if dir_raw.norm_squared() < 1e-6 {
   596→                dir_raw = Vector3::new(0.0, 0.0, 1.0);
   597→            }
   598→            let dir_norm = dir_raw.normalize();
   599→            let basis = sh_basis(&dir_norm);
   600→
   601→            // Small coefficients centered around a mid-gray via DC.
   602→            // We explicitly set the DC coefficient so the resulting base color is ~0.5
   603→            // (far from the clamp at 0/1), and keep higher-order terms tiny so the
   604→            // clamp remains inactive.
   605→            let base_r = 0.5;
   606→            let base_g = 0.5;
   607→            let base_b = 0.5;
   608→
   609→            // Retry until the clamp is comfortably inactive.
   610→            let sh_coeffs = loop {
   611→                let mut sh_coeffs = [[0.0f32; 3]; 16];
   612→                sh_coeffs[0] = [base_r / basis[0], base_g / basis[0], base_b / basis[0]];
   613→                for i in 1..16 {
   614→                    for c in 0..3 {
   615→                        sh_coeffs[i][c] = rng.gen_range(-0.001..0.001);
   616→                    }
   617→                }
   618→
   619→                let color = evaluate_sh(&sh_coeffs, &dir_raw);
   620→                if (0.2..0.8).contains(&color.x)
   621→                    && (0.2..0.8).contains(&color.y)
   622→                    && (0.2..0.8).contains(&color.z)
   623→                {
   624→                    break sh_coeffs;
   625→                }
   626→            };
   627→
   628→            // Loss weight vector (upstream gradient for color).
   629→            let w = Vector3::new(
   630→                rng.gen_range(-1.0..1.0),
   631→                rng.gen_range(-1.0..1.0),
   632→                rng.gen_range(-1.0..1.0),
   633→            );
   634→
   635→            // Analytical gradient.
   636→            let d_sh = evaluate_sh_grad_coeffs(&basis, &w);
   637→
   638→            // Numerical gradient for a random handful of coefficients.
   639→            let mut checked = 0;
   640→            for _ in 0..200 {
   641→                let i = rng.gen_range(0..16);
   642→                let c = rng.gen_range(0..3);
   643→
   644→                let mut plus = sh_coeffs;
   645→                let mut minus = sh_coeffs;
   646→                let eps = (target_delta / basis[i].abs().max(1e-3)).clamp(1e-3, 0.2);
   647→                plus[i][c] += eps;
   648→                minus[i][c] -= eps;
   649→
   650→                let f = |coeffs: &[[f32; 3]; 16]| -> f32 {
   651→                    let color = evaluate_sh(coeffs, &dir_raw);
   652→                    w.dot(&color)
   653→                };
   654→
   655→                // Skip cases where the clamp might activate for either perturbation.
   656→                // This keeps the function locally linear for finite differences.
   657→                let color_plus = evaluate_sh(&plus, &dir_raw);
   658→                let color_minus = evaluate_sh(&minus, &dir_raw);
   659→                let clamp_safe = |v: f32| (0.05..0.95).contains(&v);
   660→                if !clamp_safe(color_plus.x)
   661→                    || !clamp_safe(color_plus.y)
   662→                    || !clamp_safe(color_plus.z)
   663→                    || !clamp_safe(color_minus.x)
   664→                    || !clamp_safe(color_minus.y)
   665→                    || !clamp_safe(color_minus.z)
   666→                {
   667→                    continue;
   668→                }
   669→
   670→                // Do the subtraction in f64 to reduce cancellation/rounding error.
   671→                let f_plus = f(&plus) as f64;
   672→                let f_minus = f(&minus) as f64;
   673→                let num = ((f_plus - f_minus) / (2.0 * (eps as f64))) as f32;
   674→                let ana = d_sh[i][c];
   675→
   676→                let abs_err = (num - ana).abs();
   677→                let ok = rel_err(num, ana) < tol || abs_err < 1e-6;
   678→                assert!(
   679→                    ok,
   680→                    "SH grad mismatch at i={i} c={c}: num={num} ana={ana} abs_err={abs_err} rel_err={} basis_i={} w={:?}",
   681→                    rel_err(num, ana),
   682→                    basis[i],
   683→                    w
   684→                );
   685→
   686→                checked += 1;
   687→                if checked >= 20 {
   688→                    break;
   689→                }
   690→            }
   691→            assert!(
   692→                checked >= 20,
   693→                "Expected to check >= 20 coefficient grads, got {checked}"
   694→            );
   695→        }
   696→    }
