   698→    #[test]
   699→    fn test_covariance_projection_point_gradient() {
   700→        // Gradient check for dependence on point_cam through the perspective Jacobian J(point_cam).
   701→        let mut rng = StdRng::seed_from_u64(0xB01A_7CA1_u64);
   702→
   703→        for _ in 0..200 {
   704→            let cam_q = nalgebra::UnitQuaternion::from_euler_angles(
   705→                rng.gen_range(-1.0f32..1.0f32),
   706→                rng.gen_range(-1.0f32..1.0f32),
   707→                rng.gen_range(-1.0f32..1.0f32),
   708→            );
   709→            let w = cam_q.to_rotation_matrix().into_inner();
   710→
   711→            let g_q = nalgebra::UnitQuaternion::from_euler_angles(
   712→                rng.gen_range(-1.0f32..1.0f32),
   713→                rng.gen_range(-1.0f32..1.0f32),
   714→                rng.gen_range(-1.0f32..1.0f32),
   715→            );
   716→            let r = g_q.to_rotation_matrix().into_inner();
   717→
   718→            let log_scale = nalgebra::Vector3::new(
   719→                rng.gen_range(-4.0f32..-0.5f32),
   720→                rng.gen_range(-4.0f32..-0.5f32),
   721→                rng.gen_range(-4.0f32..-0.5f32),
   722→            );
   723→
   724→            let point_cam = nalgebra::Vector3::new(
   725→                rng.gen_range(-0.5f32..0.5f32),
   726→                rng.gen_range(-0.5f32..0.5f32),
   727→                rng.gen_range(1.0f32..4.0f32),
   728→            );
   729→
   730→            let fx = rng.gen_range(100.0f32..400.0f32);
   731→            let fy = rng.gen_range(100.0f32..400.0f32);
   732→
   733→            let g00 = rng.gen_range(-1.0f32..1.0f32);
   734→            let g01 = rng.gen_range(-1.0f32..1.0f32);
   735→            let g11 = rng.gen_range(-1.0f32..1.0f32);
   736→            let d_sigma2d = nalgebra::Matrix2::new(g00, g01, g01, g11);
   737→
   738→            let ana = project_covariance_2d_grad_point_cam(
   739→                &point_cam, fx, fy, &w, &r, &log_scale, &d_sigma2d,
   740→            );
   741→
   742→            // f64 numeric derivative of L = <G, J Σ_cam Jᵀ>
   743→            let w64 = w.map(|x| x as f64);
   744→            let r64 = r.map(|x| x as f64);
   745→            let g64 = d_sigma2d.map(|x| x as f64);
   746→            let s64 = log_scale.map(|x| x as f64);
   747→
   748→            let v = nalgebra::Vector3::new(
   749→                (2.0 * s64.x).exp(),
   750→                (2.0 * s64.y).exp(),
   751→                (2.0 * s64.z).exp(),
   752→            );
   753→            let d = nalgebra::Matrix3::from_diagonal(&v);
   754→            let sigma = r64 * d * r64.transpose();
   755→            let sigma_cam = w64 * sigma * w64.transpose();
   756→
   757→            let loss64 = |p: nalgebra::Vector3<f64>| -> f64 {
   758→                let j = {
   759→                    let x = p.x;
   760→                    let y = p.y;
   761→                    let z = p.z;
   762→                    let z_inv = 1.0 / z;
   763→                    let z_inv2 = z_inv * z_inv;
   764→                    nalgebra::Matrix2x3::new(
   765→                        (fx as f64) * z_inv,
   766→                        0.0,
   767→                        -(fx as f64) * x * z_inv2,
   768→                        0.0,
   769→                        (fy as f64) * z_inv,
   770→                        -(fy as f64) * y * z_inv2,
   771→                    )
   772→                };
   773→                let sigma2d = j * sigma_cam * j.transpose();
   774→                (sigma2d.component_mul(&g64)).sum()
   775→            };
   776→
   777→            let eps = 1e-4f64;
   778→            for axis in 0..3 {
   779→                let mut plus = point_cam.map(|x| x as f64);
   780→                let mut minus = point_cam.map(|x| x as f64);
   781→                plus[axis] += eps;
   782→                minus[axis] -= eps;
   783→                let num = (loss64(plus) - loss64(minus)) / (2.0 * eps);
   784→                let num_f32 = num as f32;
   785→
   786→                let got = ana[axis];
   787→                let abs_err = (got - num_f32).abs();
   788→                assert!(
   789→                    rel_err(got, num_f32) < 5e-4 || abs_err < 5e-4,
   790→                    "cov proj point grad mismatch axis={axis}: num={num_f32} ana={got} abs_err={abs_err} rel_err={}",
   791→                    rel_err(got, num_f32)
   792→                );
   793→            }
   794→        }
   795→    }
