   848→            let g_cov = nalgebra::Matrix2::new(g00, g01, g01, g11);
   849→
   850→            // Analytic gradients.
   851→            let d_point_from_mean = project_point_grad_point_cam(&point_cam, fx, fy, &w_uv);
   852→            let d_point_from_cov = project_covariance_2d_grad_point_cam(
   853→                &point_cam, fx, fy, &w, &r0, &log_scale, &g_cov,
   854→            );
   855→            let d_point = d_point_from_mean + d_point_from_cov;
   856→
   857→            let j = perspective_jacobian(&point_cam, fx, fy);
   858→            let d_log_scale = project_covariance_2d_grad_log_scale(&w, &j, &r0, &log_scale, &g_cov);
   859→            let d_rot =
   860→                project_covariance_2d_grad_rotation_vector_at_r0(&w, &j, &r0, &log_scale, &g_cov);
   861→
   862→            // Numeric gradients in f64.
   863→            let w64 = w.map(|x| x as f64);
   864→            let r0_64 = r0.map(|x| x as f64);
   865→            let log_scale64 = log_scale.map(|x| x as f64);
   866→            let g_cov64 = g_cov.map(|x| x as f64);
   867→
   868→            let d_vec = nalgebra::Vector3::new(
   869→                (2.0 * log_scale64.x).exp(),
   870→                (2.0 * log_scale64.y).exp(),
   871→                (2.0 * log_scale64.z).exp(),
   872→            );
   873→            let d_mat = nalgebra::Matrix3::from_diagonal(&d_vec);
   874→
   875→            let sigma = r0_64 * d_mat * r0_64.transpose();
   876→            let _sigma_cam = w64 * sigma * w64.transpose();
   877→
   878→            let loss64 = |p: nalgebra::Vector3<f64>,
   879→                          s: nalgebra::Vector3<f64>,
   880→                          r: nalgebra::Matrix3<f64>|
   881→             -> f64 {
   882→                let uv = {
   883→                    let x = p.x;
   884→                    let y = p.y;
   885→                    let z = p.z;
   886→                    nalgebra::Vector2::new(
   887→                        (fx as f64) * x / z + (cx as f64),
   888→                        (fy as f64) * y / z + (cy as f64),
   889→                    )
   890→                };
   891→
   892→                let d_vec =
   893→                    nalgebra::Vector3::new((2.0 * s.x).exp(), (2.0 * s.y).exp(), (2.0 * s.z).exp());
   894→                let d_mat = nalgebra::Matrix3::from_diagonal(&d_vec);
   895→                let sigma = r * d_mat * r.transpose();
   896→                let sigma_cam = w64 * sigma * w64.transpose();
   897→
   898→                let j = {
   899→                    let x = p.x;
   900→                    let y = p.y;
   901→                    let z = p.z;
   902→                    let z_inv = 1.0 / z;
   903→                    let z_inv2 = z_inv * z_inv;
   904→                    nalgebra::Matrix2x3::new(
   905→                        (fx as f64) * z_inv,
   906→                        0.0,
   907→                        -(fx as f64) * x * z_inv2,
   908→                        0.0,
   909→                        (fy as f64) * z_inv,
   910→                        -(fy as f64) * y * z_inv2,
   911→                    )
   912→                };
   913→                let sigma2d = j * sigma_cam * j.transpose();
   914→                let l_cov = (sigma2d.component_mul(&g_cov64)).sum();
   915→                let l_mean = (uv.x * (w_uv.x as f64)) + (uv.y * (w_uv.y as f64));
   916→                l_mean + l_cov
   917→            };
   918→
   919→            // Point_cam numeric.
   920→            let eps_p = 1e-4f64;
   921→            let p0 = point_cam.map(|x| x as f64);
   922→            for axis in 0..3 {
   923→                let mut plus = p0;
   924→                let mut minus = p0;
   925→                plus[axis] += eps_p;
   926→                minus[axis] -= eps_p;
   927→                let num = (loss64(plus, log_scale64, r0_64) - loss64(minus, log_scale64, r0_64))
   928→                    / (2.0 * eps_p);
   929→                let num_f32 = num as f32;
   930→                let got = d_point[axis];
   931→                let abs_err = (got - num_f32).abs();
   932→                assert!(
   933→                    rel_err(got, num_f32) < 5e-4 || abs_err < 5e-4,
   934→                    "combined d_point mismatch axis={axis}: num={num_f32} ana={got} abs_err={abs_err} rel_err={}",
   935→                    rel_err(got, num_f32)
   936→                );
   937→            }
   938→
   939→            // log_scale numeric.
   940→            let eps_s = 1e-4f64;
   941→            let s0 = log_scale64;
   942→            for axis in 0..3 {
   943→                let mut plus = s0;
   944→                let mut minus = s0;
   945→                plus[axis] += eps_s;
   946→                minus[axis] -= eps_s;
   947→                let num = (loss64(p0, plus, r0_64) - loss64(p0, minus, r0_64)) / (2.0 * eps_s);
   948→                let num_f32 = num as f32;
   949→                let got = d_log_scale[axis];
   950→                let abs_err = (got - num_f32).abs();
   951→                assert!(
   952→                    rel_err(got, num_f32) < 5e-4 || abs_err < 5e-4,
   953→                    "combined d_log_scale mismatch axis={axis}: num={num_f32} ana={got} abs_err={abs_err} rel_err={}",
   954→                    rel_err(got, num_f32)
   955→                );
   956→            }
   957→
   958→            // rotation-vector numeric around r0 (left-multiply small axis rotations).
   959→            let rot_x = |theta: f64| -> nalgebra::Matrix3<f64> {
   960→                let (s, c) = theta.sin_cos();
   961→                nalgebra::Matrix3::new(1.0, 0.0, 0.0, 0.0, c, -s, 0.0, s, c)
   962→            };
   963→            let rot_y = |theta: f64| -> nalgebra::Matrix3<f64> {
   964→                let (s, c) = theta.sin_cos();
   965→                nalgebra::Matrix3::new(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c)
   966→            };
   967→            let rot_z = |theta: f64| -> nalgebra::Matrix3<f64> {
   968→                let (s, c) = theta.sin_cos();
   969→                nalgebra::Matrix3::new(c, -s, 0.0, s, c, 0.0, 0.0, 0.0, 1.0)
   970→            };
   971→
   972→            let eps_r = 1e-4f64;
   973→            let num_rx = (loss64(p0, s0, rot_x(eps_r) * r0_64)
   974→                - loss64(p0, s0, rot_x(-eps_r) * r0_64))
   975→                / (2.0 * eps_r);
   976→            let num_ry = (loss64(p0, s0, rot_y(eps_r) * r0_64)
   977→                - loss64(p0, s0, rot_y(-eps_r) * r0_64))
   978→                / (2.0 * eps_r);
   979→            let num_rz = (loss64(p0, s0, rot_z(eps_r) * r0_64)
   980→                - loss64(p0, s0, rot_z(-eps_r) * r0_64))
   981→                / (2.0 * eps_r);
   982→
   983→            let num_r = nalgebra::Vector3::new(num_rx as f32, num_ry as f32, num_rz as f32);
   984→            for axis in 0..3 {
   985→                let got = d_rot[axis];
   986→                let reference = num_r[axis];
   987→                let abs_err = (got - reference).abs();
   988→                assert!(
   989→                    rel_err(got, reference) < 5e-4 || abs_err < 5e-4,
   990→                    "combined d_rot mismatch axis={axis}: num={reference} ana={got} abs_err={abs_err} rel_err={}",
   991→                    rel_err(got, reference)
   992→                );
   993→            }
   994→        }
